arguments.content:
# Ops gateway service definition.
variable "environment" { default = "production" }
variable "min_replicas" { default = 6 }
# Secrets are injected from the platform vault, never committed here.

# Historian and jump host definition.
variable "esp_zone" { default = "cip-high" }
variable "vendor_access" { default = false }

# EDC environment definition.
variable "gxp_validated" { default = true }
variable "retention_years" { default = 25 }
